Ltac lia ::= first [ zify_prune_sub; Zify.zify; xlia zchecker
                   | zify_prune; first [ zify_noeuclid; Z.euclidean_division_equations_cleanup; xlia zchecker | Zify.zify; xlia zchecker ]
                   | Zify.zify; xlia zchecker ].
Ltac tlia ::= sf_clear_big;
              first [ zify_prune_sub; Zify.zify; xlia zchecker
                    | Zify.zify; xlia zchecker
                    | sf_unhide;
                      first [ unpark_all; zify_prune_sub; Zify.zify; xlia zchecker
                            | zify_prune_neg; Zify.zify; xlia zchecker
                            | zify_prune_plain; Zify.zify; xlia zchecker
                            | Zify.zify; xlia zchecker ] ].

(* [comment removed for export] *)
Local Ltac in_live_tac ::=
  repeat match goal with H : rt_live _ _ = _ |- _ => rewrite H end;
  repeat first [ eassumption | left; reflexivity
               | apply pm_copy_live_pix | apply pm_copy_live_data | apply pm_copy_live_cmap; solve [assumption]
               | apply pm_copy_live_sub; solve [eassumption]
               | apply in_or_app; right; right; right
               | right ].
Local Ltac live_sub_tac ::=
  let e := fresh "e" in let He := fresh "He" in intros e He;
  try solve [destruct He];
  first [ match goal with S : forall x, In x ?l -> In x ?l' |- In _ ?l' => lazymatch type of He with In _ l => exact (S _ He) end end
        | repeat match goal with H : rt_live _ _ = _ |- _ => rewrite H in * end;
          repeat first [ exact He
                       | match goal with S : forall x, In x ?l -> In x ?l' |- In _ ?l' => lazymatch type of He with In _ l => exact (S _ He) end end
                       | apply pm_copy_live_sub; exact He
                       | apply in_or_app; right; right; right; exact He
                       | right ] ].
Ltac show_pc := lazymatch goal with
  | |- cps _ (ASTA _ _ _ (eq (MS _ _ ?pc _ _ _ _))) _ => idtac "CPS-MS pc=" pc
  | |- cps _ (ASTA _ _ _ (eq ?st)) _ => idtac "CPS other"
  | |- evt _ _ (MS _ _ ?pc _ _ _ _) => idtac "EVT pc=" pc
  | |- ?g => idtac "OTHER" end.


